import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

def task_func(json_data: str, key_path: list):
    if not isinstance(json_data, str) or not json_data.strip():
        raise ValueError("The data string is empty or corrupted.")

    try:
        data = json.loads(json_data)
    except Exception as exc:
        raise ValueError("The data string is empty or corrupted.") from exc

    def traverse(obj, path):
        current = obj
        for key in path:
            if isinstance(current, dict):
                if key not in current:
                    raise KeyError(key)
                current = current[key]
            elif isinstance(current, (list, tuple)):
                idx = key
                if isinstance(idx, str):
                    if idx.isdigit() or (idx.startswith("-") and idx[1:].isdigit()):
                        idx = int(idx)
                    else:
                        raise KeyError(key)
                if not isinstance(idx, int) or idx < 0 or idx >= len(current):
                    raise KeyError(key)
                current = current[idx]
            else:
                raise KeyError(key)
        return current

    def collect_numbers(obj):
        numbers = []

        if isinstance(obj, (bool, np.bool_)):
            return numbers

        if isinstance(obj, (int, float, np.integer, np.floating)):
            numbers.append(float(obj))
            return numbers

        if isinstance(obj, dict):
            for value in obj.values():
                numbers.extend(collect_numbers(value))
        elif isinstance(obj, (list, tuple, set)):
            for item in obj:
                numbers.extend(collect_numbers(item))

        return numbers

    target = traverse(data, key_path or [])
    values = collect_numbers(target)

    if not values:
        raise ValueError("No numeric data found.")

    fig, ax = plt.subplots(figsize=(6, 4))
    df = pd.DataFrame({"values": values})
    sns.boxplot(y="values", data=df, ax=ax, color="skyblue")
    ax.set_title("Boxplot of Extracted Numerical Data")
    ax.set_ylabel("Values")
    ax.set_xlabel("")
    plt.tight_layout()
    return fig
